<?php for($i=0;$i<$offset;$i++): ?><div class="calendar-day empty"></div><?php endfor; for($day=1;$day<=$daysInMonth;$day++): $dateKey=$monthParam.'-'.str_pad((string)$day,2,'0',STR_PAD_LEFT); $dayRows=$movementDays[$dateKey]??[]; $dayEvents=$eventDays[$dateKey]??[]; $hasExpense=false;$hasIncome=false;foreach($dayRows as $dr){if($dr['type']==='income')$hasIncome=true;else $hasExpense=true;} ?><button class="calendar-day <?= $dateKey===date('Y-m-d')?'today-day':'' ?>" type="button" data-date="<?= e($dateKey) ?>" onclick="selectCalendarDate('<?= e($dateKey) ?>')"><span><?= $day ?></span><?php if($hasExpense): ?><i class="day-dot expense-dot"></i><?php endif; ?><?php if($hasIncome): ?><i class="day-dot income-dot"></i><?php endif; ?><?php if($dayEvents): ?><span class="calendar-event-marker" title="<?= e(implode(', ',array_column($dayEvents,'title'))) ?>" aria-label="Recordatorios: <?= e(implode(', ',array_column($dayEvents,'title'))) ?>">♧</span><?php endif; ?></button><?php endfor; ?></div><div class="calendar-legend"><span><i class="day-dot expense-dot"></i> Gastos</span><span><i class="day-dot income-dot"></i> Ingresos</span><span><b class="calendar-event-marker legend-event">♧</b> Recordatorios</span><span>Selecciona un día para filtrar sus movimientos.</span></div></section>
