</option><option value="subscription">Suscripción</option><option value="reminder">Recordatorio</option></select></label><label>Fecha<input type="date" name="event_date" min="<?= date('Y-m-d') ?>" required></label><label>Hora<input type="time" name="event_time"></label><label>Monto<input type="number" name="amount" min="0" value="0"></label><label>Notas<input name="notes" placeholder="Detalles opcionales"></label><label class="check"><input type="checkbox" name="recurring" value="1"> Se repite</label><button class="btn primary full">Guardar recordatorio</button></form></article></section><section class="panel"><h2>Próximos eventos</h2><?php if(!$events)emptyState('No tienes recordatorios pendientes.'); foreach($events as $ev){$days=(int)floor((strtotime($ev['event_date'])-strtotime(date('Y-m-d')))/86400); ?><div class="activity-row"><div class="grow"><b><?= e($ev['title']) ?></b><small><?= e($ev['event_date']) ?> · <?= e($ev['event_type']) ?> · <?= $days===0?'¡Es hoy!':($days>0?'En '.$days.' días':'Fecha pasada') ?></small></div><strong><?= money($ev['amount']) ?></strong><form method="post" action="?page=calendario"><?= csrf_field() ?><input type="hidden" name="action" value="delete_event"><input type="hidden" name="id" value="<?= (int)$ev['id'] ?>"><button class="icon-btn">×</button></form></div><?php } ?></section>
