ied_at'])?e(date('d/m/Y H:i',strtotime($t['replied_at']))):'' ?></small></div><?php } ?><form class="ticket-actions" method="post" action="?page=soporte"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><label>Estado<select name="status"><option value="open" <?= $t['status']==='open'?'selected':'' ?>>Pendiente</option><option value="in_progress" <?= $t['status']==='in_progress'?'selected':'' ?>>En proceso</option><option value="closed" <?= $t['status']==='closed'?'selected':'' ?>>Cerrada</option></select></label><button class="btn small secondary" name="action" value="ticket_status">Guardar estado</button></form><form method="post" action="?page=soporte" class="reply-form"><?= csrf_field() ?><input type="hidden" name="action" value="ticket_reply"><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><label>Responder al usuario<textarea name="reply" rows="3" required placeholder="Escribe una respuesta clara y amable..."><?= e($t['reply_text']??'') ?></textarea></label><button class="btn small primary">Enviar respuesta</button></form></article><?php } ?></section>
